"use strict";(globalThis.webpackChunkblogseq=globalThis.webpackChunkblogseq||[]).push([[141],{1474:e=>{e.exports=JSON.parse('{"permalink":"/blogseq/2025/12/15/simulating-mutation-observer","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-12-15-simulating-mutation-observer.md","source":"@site/blog/2025-12-15-simulating-mutation-observer.md","title":"Simulating the mutation observer","description":"The logseq-datenlp-plugin makes use of a MutationObserver in order to detect when to start parsing a block for any date related phrases using natural language processing (NLP). With the observer, the plugin is able to only parse when the user creates a new block, by pressing Enter. However, this requires monitoring the DOM, and within the plugin sandbox, this is not ideal.","date":"2025-12-15T00:00:00.000Z","tags":[],"readingTime":1.89,"hasTruncateMarker":true,"authors":[{"name":"benjypng","url":"https://github.com/benjypng","page":{"permalink":"/blogseq/authors/benjypng"},"key":"benjypng"}],"frontMatter":{"title":"Simulating the mutation observer","authors":["benjypng"]},"unlisted":false,"nextItem":{"title":"Handling properties as a plugin","permalink":"/blogseq/2025/12/11/handling-props-as-plugin"}}')},5063:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>o,toc:()=>h});var o=n(1474),i=n(4848),s=n(8453);const a={title:"Simulating the mutation observer",authors:["benjypng"]},r=void 0,l={authorsImageUrls:[void 0]},h=[];function c(e){const t={code:"code",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:["The ",(0,i.jsx)(t.code,{children:"logseq-datenlp-plugin"})," makes use of a ",(0,i.jsx)(t.code,{children:"MutationObserver"})," in order to detect when to start parsing a block for any date related phrases using natural language processing (NLP). With the observer, the plugin is able to only parse when the user creates a new block, by pressing ",(0,i.jsx)(t.code,{children:"Enter"}),". However, this requires monitoring the DOM, and within the plugin sandbox, this is not ideal."]}),"\n",(0,i.jsx)(t.p,{children:"I was fiddling around with other approaches during the holidays, and found an approach that I am sufficiently pleased with."}),"\n",(0,i.jsxs)(t.p,{children:["Logseq's API provides many ways to monitor changes in the app, whether it is at the DB level or user interaction level. The closest API to an observer will be the ",(0,i.jsx)(t.code,{children:"DB.onChanged"})," hook. It allows the plugin to hook into any DB level changes."]}),"\n",(0,i.jsxs)(t.p,{children:["By using ",(0,i.jsx)(t.code,{children:"txMeta.outlinerOp"}),", the plugin can monitor for specific changes, such as when a block is saved or when a block is added; with the latter being the closest to what we need."]}),"\n",(0,i.jsxs)(t.p,{children:["My initial implementation (below) involved parsing the block each time it is saved, and then only update the block when the user inserts new blocks. While this approach worked, if the user presses ",(0,i.jsx)(t.code,{children:"Enter"})," too quickly after typing the content in the block, the parsing does not fire because transactions are batched."]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-typescript",children:"let content = ''\nlet targetBlkUuid = ''\nswitch (txMeta.outlinerOp) {\n    case 'save-block': {\n      const newContent = await parse.inlineParsing(blocks[0])\n      if (newContent) {\n        content = newContent\n        targetBlkUuid = blocks[0].uuid\n      }\n      break\n    }\n    case 'insert-blocks':\n      await logseq.Editor.updateBlock(targetBlkUuid, content)\n      break\n  }\n"})}),"\n",(0,i.jsxs)(t.p,{children:["I tried other approaches, but could not get them to work. Strangely, when I got up in the middle of the night to go to the bathroom, I suddenly thought of a much simpler approach. What if I grab the UUID of the block ",(0,i.jsx)(t.strong,{children:"when"})," it is inserted, and then immediately grab the previous sibling. So I landed on the implementation below:"]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-typescript",children:"switch (txMeta.outlinerOp) {\n  case 'insert-blocks': {\n    const currBlkUuid = await logseq.Editor.checkEditing()\n    if (!currBlkUuid) return\n\n    const prevSiblingBlk = await logseq.Editor.getPreviousSiblingBlock(\n      currBlkUuid as string,\n    )\n    if (!prevSiblingBlk) return\n\n    const newContent = await parse.inlineParsing(prevSiblingBlk)\n    if (newContent) {\n      await logseq.Editor.updateBlock(prevSiblingBlk.uuid, newContent)\n    }\n    break\n  }\n}\n"})}),"\n",(0,i.jsxs)(t.p,{children:["With the above, I am able to simulate the ",(0,i.jsx)(t.code,{children:"MutationObserver"})," without any lag. I have since migrated the ",(0,i.jsx)(t.code,{children:"logseq-datenlp-plugin"})," to the above approach and removed the need to monitor the DOM."]})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>r});var o=n(6540);const i={},s=o.createContext(i);function a(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);